'use strict';
// Safe, dependency-free .env loader — no network calls, no side effects.
const fs = require('fs');

function load(path = '.env.test') {
  const raw = fs.readFileSync(path, 'utf8');
  const cfg = {};
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue; // skip blanks & comments
    const i = trimmed.indexOf('=');
    if (i > 0) cfg[trimmed.slice(0, i).trim()] = trimmed.slice(i + 1).trim();
  }
  return cfg;
}

if (require.main === module) {
  const config = load(process.argv[2] || '.env.test');
  console.log('Config keys:', Object.keys(config));
}

module.exports = { load };

